using System;
using System.IO;
using System.Threading;
using System.Threading.Tasks;
using System.Globalization;
using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;
using System.Collections.Generic;
using System.Reflection;
using Xunit;

public class ConvertCharTests
{
    [Fact]
    public void AllAutoGeneratedMethodsCanExecute()
    {
        // Smoke test: ensure all auto-generated methods can be discovered
        var type = typeof(ConvertChar);
        Assert.NotNull(type);
    }

    /// <summary>
    /// 测试目的：验证 ToChar(Byte) 在正常输入下返回正确的字符
    /// </summary>
    [Fact]
    public void Test_ToChar_Byte_NormalInput()
    {
        char result = Convert.ToChar((byte)65);
        Assert.Equal('A', result);
    }

    /// <summary>
    /// 测试目的：验证 ToChar(Int32) 在边界值下的行为（0 和 65535）
    /// </summary>
    [Fact]
    public void Test_ToChar_Int32_EdgeCases()
    {
        char resultZero = Convert.ToChar(0);
        Assert.Equal((char)0, resultZero);

        char resultMax = Convert.ToChar(65535);
        Assert.Equal((char)65535, resultMax);
    }

    /// <summary>
    /// 测试目的：验证 ToChar(Int32) 在超出 char 范围时抛出 OverflowException
    /// </summary>
    [Fact]
    public void Test_ToChar_Int32_Overflow()
    {
        Assert.Throws<OverflowException>(() => Convert.ToChar(-1));
        Assert.Throws<OverflowException>(() => Convert.ToChar(65536));
    }

    /// <summary>
    /// 测试目的：验证 ToChar(String) 在单字符字符串下正常工作
    /// </summary>
    [Fact]
    public void Test_ToChar_String_NormalInput()
    {
        char result = Convert.ToChar("A");
        Assert.Equal('A', result);
    }

    /// <summary>
    /// 测试目的：验证 ToChar(String) 在 null、空字符串或多字符字符串时抛出异常
    /// </summary>
    [Fact]
    public void Test_ToChar_String_InvalidInput()
    {
        Assert.Throws<ArgumentNullException>(() => Convert.ToChar((string)null!));
        Assert.Throws<FormatException>(() => Convert.ToChar(""));
        Assert.Throws<FormatException>(() => Convert.ToChar("AB"));
    }

    /// <summary>
    /// 测试目的：验证 ToChar(Boolean) 抛出 InvalidCastException
    /// </summary>
    [Fact]
    public void Test_ToChar_Boolean_Conversion()
    {
        Assert.Throws<InvalidCastException>(() => Convert.ToChar(true));
        Assert.Throws<InvalidCastException>(() => Convert.ToChar(false));
    }

    /// <summary>
    /// 测试目的：验证 ToChar(Double) 抛出 InvalidCastException
    /// </summary>
    [Fact]
    public void Test_ToChar_Double_Conversion()
    {
        Assert.Throws<InvalidCastException>(() => Convert.ToChar(65.0));
    }

    /// <summary>
    /// 测试目的：验证 ToChar(DateTime) 始终抛出 InvalidCastException
    /// </summary>
    [Fact]
    public void Test_ToChar_DateTime_ThrowsInvalidCast()
    {
        Assert.Throws<InvalidCastException>(() => Convert.ToChar(DateTime.Now));
    }

    /// <summary>
    /// 测试目的：验证 ToChar(Decimal) 抛出 InvalidCastException
    /// </summary>
    [Fact]
    public void Test_ToChar_Decimal_Conversion()
    {
        Assert.Throws<InvalidCastException>(() => Convert.ToChar(65m));
    }

    /// <summary>
    /// 测试目的：验证 ToChar(Char) 对 char 到 char 的恒等转换
    /// </summary>
    [Fact]
    public void Test_ToChar_Char_Identity()
    {
        char result = Convert.ToChar('Z');
        Assert.Equal('Z', result);
    }

    /// <summary>
    /// 测试目的：验证 ToChar(Single) 抛出 InvalidCastException
    /// </summary>
    [Fact]
    public void Test_ToChar_Single_Conversion()
    {
        Assert.Throws<InvalidCastException>(() => Convert.ToChar(65.0f));
    }
}
